import{_ as r,o as a,c as t,al as o}from"./chunks/framework.7vp1BMOE.js";const f=JSON.parse('{"title":"ESCs & Motors","description":"","frontmatter":{},"headers":[],"relativePath":"zh/peripherals/esc_motors.md","filePath":"zh/peripherals/esc_motors.md"}'),s={name:"zh/peripherals/esc_motors.md"};function d(n,e,h,l,i,p){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="escs-motors" tabindex="-1">ESCs &amp; Motors <a class="header-anchor" href="#escs-motors" aria-label="Permalink to &quot;ESCs &amp; Motors&quot;">​</a></h1><p>Many PX4 drones use brushless motors that are driven by the flight controller via an Electronic Speed Controller (ESC). The ESC takes a signal from the flight controller and uses it to set control the level of power delivered to the motor.</p><p>PX4 supports a number of <a href="./../esc/esc_protocols">common protocols</a> for sending the signals to ESCs: <a href="./../peripherals/pwm_escs_and_servo">PWM ESCs</a>, <a href="./../peripherals/oneshot">OneShot ESCs</a>, <a href="./../peripherals/dshot">DShot ESCs</a>, <a href="./../dronecan/escs">DroneCAN ESCs</a>, PCA9685 ESC (via I2C), and some UART ESCs (from Yuneec).</p><h2 id="supported-esc" tabindex="-1">Supported ESC <a class="header-anchor" href="#supported-esc" aria-label="Permalink to &quot;Supported ESC&quot;">​</a></h2><p>The following list is non-exhaustive.</p><table tabindex="0"><thead><tr><th>ESC Device</th><th>Protocols</th><th>Firmwares</th><th>备注</th></tr></thead><tbody><tr><td><a href="./../esc/ark_4in1_esc">ARK 4IN1 ESC</a></td><td><a href="./../peripherals/dshot">Dshot</a>, <a href="./../peripherals/pwm_escs_and_servo">PWM</a></td><td><a href="https://am32.ca/" target="_blank" rel="noreferrer">AM32</a></td><td>Has versions with/without connectors</td></tr><tr><td><a href="./../peripherals/hiwonder_emm">Hiwonder 4Ch Encoder Motor</a></td><td>I2C</td><td></td><td>Brushed-DC, 4 channels with encoder feedback (rovers)</td></tr><tr><td><a href="./../dronecan/holybro_kotleta">Holybro Kotleta 20</a></td><td><a href="./../dronecan/escs">DroneCAN</a>, <a href="./../peripherals/pwm_escs_and_servo">PWM</a></td><td><a href="./../dronecan/sapog">PX4 Sapog ESC Firmware</a></td><td></td></tr><tr><td><a href="./../peripherals/vertiq">Vertiq Motor &amp; ESC modules</a></td><td><a href="./../peripherals/dshot">Dshot</a>, <a href="./../peripherals/oneshot">OneShot</a>, Multishot, <a href="./../peripherals/pwm_escs_and_servo">PWM</a></td><td>Vertiq firmware</td><td>Larger modules support DroneCAN, ESC and Motor in one</td></tr><tr><td><a href="./../dronecan/raccoonlab_nodes">RaccoonLab CAN PWM ESC nodes</a></td><td><a href="./../dronecan/escs">DroneCAN</a>, Cyphal</td><td></td><td>Cyphal and DroneCAN notes for PWM ESC</td></tr><tr><td><a href="./../peripherals/vesc">VESC ESCs</a></td><td><a href="./../dronecan/escs">DroneCAN</a>, <a href="./../peripherals/pwm_escs_and_servo">PWM</a></td><td>VESC project firmware</td><td></td></tr><tr><td><a href="./../dronecan/zubax_telega">Zubax Telega</a></td><td><a href="./../dronecan/escs">DroneCAN</a>, <a href="./../peripherals/pwm_escs_and_servo">PWM</a></td><td>Telega-based</td><td>ESC and Motor in one</td></tr></tbody></table><h2 id="另见" tabindex="-1">另见 <a class="header-anchor" href="#另见" aria-label="Permalink to &quot;另见&quot;">​</a></h2><p>有关详细信息，请参阅︰</p><ul><li><a href="./../esc/esc_protocols">ESC Protocols</a> — overview of main ESC/Servo protocols supported by PX4</li><li><a href="./../peripherals/pwm_escs_and_servo">PWM ESCs and Servos</a></li><li><a href="./../peripherals/oneshot">OneShot ESCs and Servos</a></li><li><a href="./../peripherals/dshot">DShot</a></li><li><a href="./../dronecan/escs">DroneCAN ESCs</a></li><li><a href="./../advanced_config/esc_calibration">ESC Calibration</a></li><li><a href="https://oscarliang.com/esc-firmware-protocols/" target="_blank" rel="noreferrer">ESC Firmware and Protocols Overview</a> (oscarliang.com)</li></ul>',9)])])}const _=r(s,[["render",d]]);export{f as __pageData,_ as default};
